package main

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

func newTestStore() *Store {
	return NewStore(30 * time.Minute)
}

// errorEnvelope mirrors the documented error envelope shape.
type errorEnvelope struct {
	Error struct {
		Status  int    `json:"status"`
		Code    string `json:"code"`
		Message string `json:"message"`
	} `json:"error"`
}

func decodeError(t *testing.T, rec *httptest.ResponseRecorder) errorEnvelope {
	t.Helper()
	var env errorEnvelope
	if err := json.Unmarshal(rec.Body.Bytes(), &env); err != nil {
		t.Fatalf("body is not valid JSON: %v; body=%q", err, rec.Body.String())
	}
	return env
}

func TestSessionPostMissingParamsJSONError(t *testing.T) {
	srv := httptest.NewServer(sessionHandler(newTestStore()))
	defer srv.Close()

	resp, err := http.Post(srv.URL+"/session", "", nil)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusBadRequest {
		t.Fatalf("status = %d, want 400", resp.StatusCode)
	}
	if ct := resp.Header.Get("Content-Type"); ct != "application/json" {
		t.Fatalf("Content-Type = %q, want application/json", ct)
	}
	env := decodeError(t, httptest.NewRecorder())
	_ = env

	rec := httptest.NewRecorder()
	sessionHandler(newTestStore())(rec, httptest.NewRequest(http.MethodPost, "/session", nil))
	env2 := decodeError(t, rec)
	if env2.Error.Status != http.StatusBadRequest || env2.Error.Code != "INVALID_ARGUMENT" {
		t.Fatalf("envelope = %+v, want status 400 code INVALID_ARGUMENT", env2.Error)
	}
	if env2.Error.Message == "" {
		t.Fatal("error.message is empty")
	}
}

func TestSessionGetNotFoundJSONError(t *testing.T) {
	rec := httptest.NewRecorder()
	sessionHandler(newTestStore())(rec, httptest.NewRequest(http.MethodGet, "/session?id=missing", nil))

	if rec.Code != http.StatusNotFound {
		t.Fatalf("status = %d, want 404", rec.Code)
	}
	if ct := rec.Header().Get("Content-Type"); ct != "application/json" {
		t.Fatalf("Content-Type = %q, want application/json", ct)
	}
	env := decodeError(t, rec)
